const MEAL_GLYPH_TINT={drumstick:'#f0a36b',steak:'#ec6a76',fish:'#5fc3e8',milk:'#9ec5ff',wheat:'#e8b84a',carrot:'#ff9c4a',apple:'#ef6a6a',pod:'#6fd58a',nut:'#c9965f',cup:'#6fd0e8',drop:'#f2c14e',cookie:'#e8a0c0',herb:'#58c878',bowl:'#f08e4a',plate:'#9aa7c4'};
const MEAL_SLOT_TINT={breakfast:'#f2b84a',lunch:'#5fd08a',dinner:'#6aa4f0',snacks:'#ef7a85'};
function mealGlyphKey(cat,name){
  const c=String(cat||'').toLowerCase(),n=String(name||'').toLowerCase();
  const by=[[/poultry/,'drumstick'],[/beef|pork|lamb|veal|game|sausage|luncheon/,'steak'],[/fish|shellfish|seafood/,'fish'],[/dairy|egg|milk/,'milk'],[/cereal|grain|pasta|baked|bread/,'wheat'],[/vegetable/,'carrot'],[/fruit/,'apple'],[/legume|bean/,'pod'],[/nut|seed/,'nut'],[/beverage|drink|juice/,'cup'],[/fat|oil/,'drop'],[/sweet|snack|candy|dessert/,'cookie'],[/spice|herb/,'herb'],[/soup|sauce|gravy|restaurant/,'bowl']];
  for(const [re,k] of by)if(re.test(c))return k;
  const nm=[[/chicken|turkey|duck/,'drumstick'],[/beef|steak|pork|bacon|ham|lamb|sausage/,'steak'],[/salmon|tuna|cod|shrimp|fish|sardine/,'fish'],[/milk|cheese|yogurt|yoghurt|egg|butter|cream/,'milk'],[/rice|oat|bread|pasta|noodle|cereal|wheat|flour|tortilla/,'wheat'],[/carrot|broccoli|spinach|lettuce|kale|pepper|onion|tomato|potato|salad|cucumber/,'carrot'],[/apple|banana|berry|orange|grape|mango|fruit|melon|peach|pear/,'apple'],[/bean|lentil|chickpea|pea\b|tofu/,'pod'],[/almond|peanut|walnut|cashew|nut|seed/,'nut'],[/water|juice|coffee|tea|soda|drink|shake/,'cup'],[/oil|lard|ghee/,'drop'],[/cookie|cake|candy|chocolate|sugar|honey|ice cream|dessert/,'cookie'],[/soup|stew|sauce|curry|chili/,'bowl']];
  for(const [re,k] of nm)if(re.test(n))return k;
  return 'plate';
}
function mealGlyph(cat,name,cls){const k=mealGlyphKey(cat,name);return '<span class="mlg-wrap '+(cls||'')+'" style="--c:'+MEAL_GLYPH_TINT[k]+'">'+MEAL_GLYPHS[k]+'</span>'}
function mealMacroGlyph(k){return '<span class="mlg-macro mlg-'+k+'">'+MEAL_GLYPHS[{p:'drumstick',c:'wheat',f:'drop'}[k]]+'</span>'}

/* ===== Nutrition OS / Motion Engine v54 =====
 * Cosmetic-only effects. Nothing is written to storage. All paths are based on actual
 * logged macro values, and the user can replay the visual without changing entries.
 * Particle canvas is pointer-transparent and runs for <2s per event.
 */
let fuelFxToken=0,fuelFxCanvasFrame=0,fuelFxTimers=[];
function fuelMotionAllowed(){return !fxReduced()&&!document.hidden&&!!document.getElementById('view-meals')?.classList.contains('active')}
function fuelCancelMotion(){
  fuelFxToken++;
  if(fuelFxCanvasFrame){cancelAnimationFrame(fuelFxCanvasFrame);fuelFxCanvasFrame=0}
  fuelFxTimers.forEach(clearTimeout);fuelFxTimers=[];
  document.getElementById('fuelFxLayer')?.remove();
  document.getElementById('fuelFxToast')?.remove();
  document.querySelector('#view-meals .fuel-reactor-visual')?.classList.remove('fuel-charged');
}
function fuelFxLater(fn,ms){const t=setTimeout(fn,ms);fuelFxTimers.push(t);return t}
function fuelEaseOut(x){return 1-Math.pow(1-x,3)}
function fuelFxCenter(el){const r=el.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2}}
function fuelAnimateBig(from,to){
 const el=document.getElementById('fuelCaloriesBig');if(!el)return;
 if(!fuelMotionAllowed()||Math.abs(to-from)<1){el.textContent=Math.round(to).toLocaleString();return}
 const token=fuelFxToken,start=performance.now(),dur=1000;
 function step(now){if(token!==fuelFxToken)return;const u=Math.max(0,Math.min(1,(now-start)/dur));el.textContent=Math.round(from+(to-from)*fuelEaseOut(u)).toLocaleString();if(u<1)requestAnimationFrame(step)}
 requestAnimationFrame(step);
}
function fuelSignalPulse(slot,details){
  const root=document.getElementById('view-meals');
  const visual=root?.querySelector('.fuel-reactor-visual');
  const shell=root?.querySelector('.fuel-ring-shell');
  const ringVisual=root?.querySelector('#mealsRing');
  if(!root||!visual||!shell||!ringVisual||!fuelMotionAllowed())return;
  fuelCancelMotion();
  const token=fuelFxToken;
  const reactor=root.querySelector('.fuel-reactor');
  reactor?.scrollIntoView({behavior:'smooth',block:'center'});
  fuelFxLater(()=>{
    if(token!==fuelFxToken||!fuelMotionAllowed())return;
    reactor?.scrollIntoView({behavior:'instant',block:'center'});
    requestAnimationFrame(()=>{
      if(token!==fuelFxToken||!fuelMotionAllowed())return;
      const host=visual.getBoundingClientRect(),ring=shell.getBoundingClientRect(),ringBox=ringVisual.getBoundingClientRect();
      if(host.width<10||host.height<10||ring.width<10||ringBox.width<10)return;
      const w=host.width,h=host.height;
      const ringCenter={x:ring.left-host.left+ring.width/2,y:ring.top-host.top+ring.height/2};
      const targetMap=fuelMacroTargetPoints(host,ringBox);
      const targetByLane=[targetMap.p,targetMap.c,targetMap.f];
      const demo=!!details?.demo;
      const kcal=Math.max(0,Number(details?.kcal)||0);
      const macroVals=[Math.max(0,Number(details?.p)||0),Math.max(0,Number(details?.c)||0),Math.max(0,Number(details?.f)||0)];
      const lanes=demo?[0,1,2]:macroVals.map((v,i)=>v>0?i:-1).filter(i=>i>=0);
      if(!lanes.length)lanes.push(1);
      const colors=['#8db7ff','#76f1b3','#ffda8a'];
      const labels=['PROTEIN','CARBS','FAT'];
      const layer=document.createElement('div');
      layer.id='fuelFxLayer';layer.className='fuel-fx-layer';
      layer.setAttribute('aria-hidden','true');
      const canvas=document.createElement('canvas');
      const status=document.createElement('div');
      status.className='fuel-transfer-status';
      status.textContent=demo?'REPLAYING NUTRIENT FLOW':'NUTRIENT TRANSFER IN PROGRESS';
      const markers=document.createElement('div');
      markers.className='fuel-transfer-markers';
      markers.innerHTML=lanes.map(i=>`<span>${labels[i]}</span>`).join('');
      layer.appendChild(canvas);layer.appendChild(status);layer.appendChild(markers);
      visual.appendChild(layer);
      const ctx=canvas.getContext('2d',{alpha:true});if(!ctx){layer.remove();return}
      const d=Math.min(2,window.devicePixelRatio||1);
      canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);
      ctx.setTransform(d,0,0,d,0,0);
      ctx.imageSmoothingEnabled=false;
      const sources=[
        {x:w*.14,y:h*.79},
        {x:w*.50,y:h*.87},
        {x:w*.86,y:h*.79}
      ];
      sources.forEach((o,i)=>{
        if(o.y<ringCenter.y+70)o.y=Math.min(h-40,ringCenter.y+70+(i%2)*9);
      });
      const particles=[];
      lanes.forEach((lane)=>{
        const target=targetByLane[lane]||ringCenter;
        for(let j=0;j<31;j++){
          const spread=(j%7-3)*2.8;
          const source=sources[lane];
          const midX=source.x+(target.x-source.x)*.56+(lane-1)*10;
          const midY=Math.min(source.y,target.y)-34-(j%5)*4;
          particles.push({
            lane,delay:j*.054+(lane*.08),life:1.02+(j%4)*.08,
            sx:source.x+spread,sy:source.y+(j%4-1.5)*5,
            mx:midX,my:midY,
            tx:target.x+(j%5-2)*2.2,ty:target.y+(j%4-1.5)*2.2,
            sz:j%6===0?11:j%3===0?9:7,
            tail:2+(j%3)
          });
        }
      });
      const toast=document.createElement('div');
      toast.className='fuel-fx-toast';
      toast.id='fuelFxToast';
      toast.setAttribute('aria-live','polite');
      toast.innerHTML=demo?'SIGNAL REPLAY <small>NO MEAL ADDED</small>':
        `+${Math.round(kcal).toLocaleString()} KCAL RECEIVED <small>P +${Math.round(macroVals[0]*10)/10}g · C +${Math.round(macroVals[1]*10)/10}g · F +${Math.round(macroVals[2]*10)/10}g</small>`;
      document.body.appendChild(toast);
      const started=performance.now(),duration=3.35;
      let pulse=false,shown=false;
      function draw(now){
        if(token!==fuelFxToken||!fuelMotionAllowed()){
          layer.remove();toast.remove();return
        }
        const elapsed=(now-started)/1000;
        ctx.clearRect(0,0,w,h);
        // Strong, visible source emitters
        lanes.forEach((lane)=>{
          const s=sources[lane];
          const beat=.7+.3*Math.sin(elapsed*10+lane);
          ctx.fillStyle=colors[lane];ctx.globalAlpha=beat*.8;
          ctx.fillRect(Math.round(s.x)-10,Math.round(s.y)-10,20,20);
          ctx.fillStyle='#081521';ctx.globalAlpha=1;
          ctx.fillRect(Math.round(s.x)-5,Math.round(s.y)-5,10,10);
          ctx.fillStyle=colors[lane];ctx.fillRect(Math.round(s.x)-2,Math.round(s.y)-2,4,4);
        });
        particles.forEach(p=>{
          const age=(elapsed-p.delay)/p.life;
          if(age<=0||age>=1)return;
          const t=age<.12?age/.12:age>.86?(1-age)/.14:1;
          const z=age*age*(3-2*age),u=1-z;
          const x=u*u*p.sx+2*u*z*p.mx+z*z*p.tx;
          const y=u*u*p.sy+2*u*z*p.my+z*z*p.ty;
          const size=p.sz;
          const color=colors[p.lane];
          ctx.globalAlpha=Math.max(0,t);
          ctx.fillStyle=color;
          // Bright outlined chunks read as original pixel art, not dust.
          ctx.shadowColor=color;ctx.shadowBlur=10;
          ctx.fillRect(Math.round(x),Math.round(y),size,size);
          ctx.shadowBlur=0;ctx.fillStyle='#eaf7ff';
          ctx.globalAlpha=t*.72;
          ctx.fillRect(Math.round(x)+Math.max(1,Math.floor(size/3)),Math.round(y)+1,Math.max(2,Math.floor(size/3)),2);
          // Discrete square trail aligned to the same curved path.
          for(let k=1;k<=p.tail;k++){
            const za=Math.max(0,z-k*.075),ua=1-za;
            const tx=ua*ua*p.sx+2*ua*za*p.mx+za*za*p.tx;
            const ty=ua*ua*p.sy+2*ua*za*p.my+za*za*p.ty;
            const sz=k===1?5:3;
            ctx.fillStyle=color;ctx.globalAlpha=t*(.43/k);
            ctx.fillRect(Math.round(tx),Math.round(ty),sz,sz);
          }
        });
        ctx.shadowBlur=0;ctx.globalAlpha=1;
        // Large pixel impact pulse, timed to the first arrivals.
        if(elapsed>1.05&&!pulse){
          pulse=true;
          visual.classList.remove('fuel-charged');
          void visual.offsetWidth;
          visual.classList.add('fuel-charged');
        }
        if(elapsed>1.7&&!shown){shown=true;toast.classList.add('is-on')}
        if(elapsed<duration){
          fuelFxCanvasFrame=requestAnimationFrame(draw);
        }else{
          status.textContent='TRANSFER COMPLETE';
          toast.classList.remove('is-on');
          fuelFxTimers.push(setTimeout(()=>{
            if(token===fuelFxToken){layer.remove();toast.remove();visual.classList.remove('fuel-charged')}
          },300));
          fuelFxCanvasFrame=0;
        }
      }
      fuelFxCanvasFrame=requestAnimationFrame(draw);
    });
  },750);
}
function fuelAfterLog(slot,macros,oldTotal){
 if(!fuelMotionAllowed())return;
 fuelSignalPulse(slot,macros);
 const big=document.getElementById('fuelCaloriesBig');if(big)big.textContent=Math.round(oldTotal).toLocaleString();
 const now=dayFoodLog(mealsDayKey()).reduce((a,e)=>a+(Number(e.kcal)||0),0);
 // Animate the visible energy count after the ring has received its particles.
 const token=fuelFxToken;
 fuelFxLater(()=>{if(token===fuelFxToken)fuelAnimateBig(oldTotal,now)},1260);
}
function fuelReplaySignal(){
 if(fxReduced()){toast('Energy animations are disabled by Reduced effects or your device motion preference');return}
 if(!fuelMotionAllowed())return;
 // Purely a preview. It never adds food or changes the user data.
 fuelSignalPulse(null,{demo:true,p:1,c:1,f:1,kcal:0});
}
function fuelDayTransition(){
 if(!fuelMotionAllowed())return;
 const reactor=document.querySelector('#view-meals .fuel-reactor-visual');
 reactor?.classList.remove('fuel-ring-focus');void reactor?.offsetWidth;reactor?.classList.add('fuel-ring-focus');
 fuelFxLater(()=>reactor?.classList.remove('fuel-ring-focus'),1010);
 document.querySelector('#fuelWeekChart .fuel-week-day[aria-pressed="true"]')?.classList.add('fuel-day-switched');
}

function fuelOpenLab(slot){
  const lab=document.getElementById('fuelLab');
  if(!lab)return;
  lab.open=true;
  if(slot){const el=document.getElementById('mealSlot');if(el)el.value=slot;}
  lab.scrollIntoView({behavior:(document.documentElement.classList.contains('reduce-motion')||window.matchMedia('(prefers-reduced-motion: reduce)').matches)?'auto':'smooth',block:'start'});
}
function fuelRenderWeek(activeDay,goal){
  const box=document.getElementById('fuelWeekChart');if(!box)return;
  const today=new Date(getToday()+'T12:00:00');
  const days=[];let all=0;
  for(let i=6;i>=0;i--){
    const d=new Date(today);d.setDate(d.getDate()-i);
    const key=d.toLocaleDateString('en-CA');
    const entries=dayFoodLog(key);
    const cal=entries.reduce((n,x)=>n+(Number(x.kcal)||0),0);
    all+=cal;
    days.push({key,cal,n:entries.length,name:d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,3)});
  }
  const max=Math.max(1,goal,...days.map(x=>x.cal));
  box.innerHTML=days.map(x=>{
    const pct=Math.max(0,Math.min(100,Math.round(x.cal/max*100)));
    const value=x.cal?Math.round(x.cal).toLocaleString(): '–';
    return `<button type="button" class="fuel-week-day" onclick="setMealsDay('${x.key}')" aria-pressed="${x.key===activeDay}" aria-label="${x.name}: ${Math.round(x.cal)} calories across ${x.n} entries. View day."><span class="fuel-week-value">${value}</span><span class="fuel-week-track"><i class="fuel-week-fill" style="--pct:${pct}%"></i></span><span class="fuel-week-label">${x.name}</span></button>`;
  }).join('');
  const total=document.getElementById('fuelWeekTotal');
  if(total)total.textContent=all?Math.round(all).toLocaleString()+' KCAL / LAST 7 DAYS':'NO FOOD LOGGED IN THE LAST 7 DAYS';
}
function fuelRenderStations(entries){
  const box=document.getElementById('fuelStations');if(!box)return;
  const slots=['breakfast','lunch','dinner','snacks'];
  const names={breakfast:'Breakfast',lunch:'Lunch',dinner:'Dinner',snacks:'Snacks'};
  const hint={breakfast:'Start the day well',lunch:'Midday fuel',dinner:'The evening plate',snacks:'Little extras'};
  const share={breakfast:.25,lunch:.30,dinner:.35,snacks:.10};
  const goal=Math.max(0,Number(state.mealsMeta&&state.mealsMeta.calGoal)||0);
  box.innerHTML=slots.map((slot,i)=>{
    const list=entries.filter(x=>x.slot===slot),cal=Math.round(list.reduce((n,x)=>n+(Number(x.kcal)||0),0));
    const p=list.reduce((n,x)=>n+(Number(x.p)||0),0),c=list.reduce((n,x)=>n+(Number(x.c)||0),0),f=list.reduce((n,x)=>n+(Number(x.f)||0),0),tot=(p*4+c*4+f*9)||1;
    const budget=goal?Math.round(goal*share[slot]):0,pct=budget?Math.min(100,Math.round(cal/budget*100)):0,over=budget&&cal>budget*1.1;
    const mix=list.length?'<div class="fs-mix" aria-hidden="true"><i style="flex:'+(p*4/tot).toFixed(3)+';background:#5b8cff"></i><i style="flex:'+(c*4/tot).toFixed(3)+';background:#3dd68c"></i><i style="flex:'+(f*9/tot).toFixed(3)+';background:#e8b84a"></i></div>':'<div class="fs-mix is-blank" aria-hidden="true"></div>';
    const sub=list.length?list.length+' '+(list.length===1?'item':'items')+(budget?' · '+(over?'over':'of ~'+budget.toLocaleString())+' plan':''):hint[slot];
    return `<button type="button" class="fuel-station${list.length?' has':''}${over?' over':''}" style="--c:${MEAL_SLOT_TINT[slot]}" onclick="openMealSheet('${slot}')" aria-label="Add food to ${names[slot]}"><span class="fs-icon">${MEALS_PIXEL_ICONS[slot]}</span><span class="fs-head"><span class="fs-id"><small>MEAL 0${i+1}</small><b>${names[slot]}</b></span><span class="fs-plus" aria-hidden="true">+</span></span><span class="fs-kcal"><b>${cal.toLocaleString()}</b><small>KCAL</small></span>${budget?'<span class="fs-bar" aria-hidden="true"><i style="width:'+pct+'%"></i></span>':''}${mix}<span class="fs-sub">${sub}</span></button>`;
  }).join('');
}
function fuelRenderLog(entries){
 const box=document.getElementById('mealsLog');if(!box)return;
 const names={breakfast:'Breakfast',lunch:'Lunch',dinner:'Dinner',snacks:'Snacks'};
 const slots=['breakfast','lunch','dinner','snacks'];
 box.innerHTML=slots.map((slot,i)=>{
  const list=entries.filter(e=>e.slot===slot),cal=list.reduce((a,e)=>a+(Number(e.kcal)||0),0);
  const rows=list.map(e=>{const fd=(typeof foodById==='function'&&foodById(e.foodId))||null,eid=String(e.id).replace(/'/g,"\\'");
   return `<div class="fuel-log-row">${mealGlyph(fd&&fd.cat,e.name,'fl-ic')}<div class="fl-txt"><strong>${esc(e.name)}</strong><small>${Number(e.grams)||0} g${e.kcalEstimated?' · estimated':''}</small><span class="fl-chips"><em class="p">P ${Number(e.p)||0}</em><em class="c">C ${Number(e.c)||0}</em><em class="f">F ${Number(e.f)||0}</em></span></div><span class="fuel-log-energy">${e.kcalEstimated?'≈':''}${Math.round(Number(e.kcal)||0)}<small>KCAL</small></span><button class="fl-del" type="button" aria-label="Remove ${esc(e.name)}" onclick="deleteMealEntry('${eid}')">${MEAL_GLYPHS.trash}</button></div>`}).join('');
  return `<div class="fuel-log-block" style="--c:${MEAL_SLOT_TINT[slot]}"><div class="fuel-log-head"><span class="fuel-log-icon">${MEALS_PIXEL_ICONS[slot]}</span><div><h4 class="fuel-log-name">${names[slot]}</h4><div class="fuel-log-hint">${list.length?list.length+' '+(list.length===1?'item':'items')+' logged':'Nothing logged yet'}</div></div><div class="fuel-log-kcal">${Math.round(cal).toLocaleString()}<small>KCAL</small></div></div><div class="fuel-log-items">${list.length?rows:'<div class="fuel-log-empty">Nothing here yet. Add your first food whenever you like.</div>'}<button class="fuel-log-add" type="button" onclick="openMealSheet('${slot}')"><span aria-hidden="true">+</span> Add to ${names[slot].toLowerCase()}</button></div></div>`;
 }).join('');
}
function renderMeals(){
  mealsEnsure();renderDietPlan();
  if(!mealsDay)mealsDay=getToday();
  const day=mealsDay,entries=dayFoodLog(day);
  const totals=entries.reduce((a,e)=>({kcal:a.kcal+(Number(e.kcal)||0),p:a.p+(Number(e.p)||0),c:a.c+(Number(e.c)||0),f:a.f+(Number(e.f)||0)}),{kcal:0,p:0,c:0,f:0});
  const goal=Math.max(0,Number(state.mealsMeta.calGoal)||0),pct=goal?Math.min(100,Math.round(totals.kcal/goal*100)):0;
  const label=document.getElementById('mealsDayLabel'),title=document.getElementById('mealsDayTitle');
  if(!label||!title)return;
  label.textContent=day===getToday()?'TODAY':'VIEWING DAY';
  try{title.textContent=new Date(day+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}catch(e){title.textContent=day}
  document.getElementById('mealsCalBar').style.width=pct+'%';
  document.getElementById('mealsCalText').textContent=goal?`${Math.round(totals.kcal).toLocaleString()} / ${goal.toLocaleString()}`:`${Math.round(totals.kcal).toLocaleString()} kcal logged`;
  document.getElementById('mealsMacroText').textContent=`P ${Math.round(totals.p)} · C ${Math.round(totals.c)} · F ${Math.round(totals.f)}`;
  document.getElementById('mealsP').textContent=Math.round(totals.p)+'g';
  document.getElementById('mealsC').textContent=Math.round(totals.c)+'g';
  document.getElementById('mealsF').textContent=Math.round(totals.f)+'g';
  document.getElementById('mealsN').textContent=entries.length;
  const legP=document.getElementById('legP'),legC=document.getElementById('legC'),legF=document.getElementById('legF');
  if(legP){legP.textContent=Math.round(totals.p)+'g';legC.textContent=Math.round(totals.c)+'g';legF.textContent=Math.round(totals.f)+'g'}
  const big=document.getElementById('fuelCaloriesBig');if(big)big.textContent=Math.round(totals.kcal).toLocaleString();
  const remain=document.getElementById('mealsRemaining');
  if(remain){if(goal){const diff=goal-totals.kcal;remain.textContent=diff>=0?`${Math.round(diff).toLocaleString()} kcal until your daily target.`:`${Math.round(Math.abs(diff)).toLocaleString()} kcal above your set target.`}else remain.textContent=entries.length?'Your food record updates in real time.':'Your day starts here. Add food to see it come alive.';if(entries.some(e=>e.kcalEstimated))remain.textContent+=' Some energy values are macro estimates.'}
  const status=document.getElementById('mealsStatusChip');if(status)status.textContent=goal?`${pct}% OF TARGET`:(entries.length?`${entries.length} ENTRIES TODAY`:'AWAITING FIRST ENTRY');
  const help=document.getElementById('mealsGoalHelper');if(help)help.textContent=goal?'OF DAILY TARGET':'SET A TARGET';
  const goalInput=document.getElementById('mealsCalGoal');if(goalInput&&document.activeElement!==goalInput)goalInput.value=goal||'';
  renderMealsRing(totals,goal);
  fuelRenderWeek(day,goal);
  fuelRenderStations(entries);
  fuelRenderLog(entries);
}

